<?php
require __DIR__.'/../src/Support.php'; require __DIR__.'/../src/DingTalk.php'; require __DIR__.'/../src/Proxy.php';
use PiDingding\{Support,DingTalk,Proxy};
$env=fn($k,$d='')=>getenv($k)!==false?getenv($k):$d; $body=file_get_contents('php://input'); $path=parse_url($_SERVER['REQUEST_URI']??'/',PHP_URL_PATH);
header('Content-Type: application/json; charset=utf-8'); if($path==='/health'){echo json_encode(['ok'=>true]);exit;} if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);echo json_encode(['error'=>'POST required']);exit;}
$headers=function_exists('getallheaders')?getallheaders():[]; $ding=new DingTalk($env('DD_APP_SECRET'),filter_var($env('DD_VERIFY_SIGNATURE','1'),FILTER_VALIDATE_BOOL)); if(!$ding->verify($headers)){http_response_code(403);echo json_encode(['error'=>'invalid signature']);exit;}
$data=json_decode($body,true)?:[]; $text=trim($data['text']['content']??$data['text']??''); $user=$data['senderStaffId']??$data['senderId']??'default'; $projects=$env('PI_PROJECTS_FILE','/root/.pi-web/projects.json'); $sessionDir=$env('PI_SESSION_DIR','/root/.pi/agent/sessions'); $stateFile=$env('PI_STATE_FILE',__DIR__.'/../var/state.json'); $proxy=new Proxy(new Support($projects,$sessionDir),$env('PI_BIN','pi'),(int)$env('PI_TIMEOUT','600'),$stateFile,(int)$env('PI_RUNNING_WINDOW','300'));
